import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';

// Generated by tools/gen-sounds.mjs (2.8–4.2 kHz: where hearing is most sensitive).
const SOURCES = {
  chime: require('../../assets/sounds/chime.wav'),
  warning: require('../../assets/sounds/alarm_warning.wav'),
  critical: require('../../assets/sounds/alarm_critical.wav'),
  siren: require('../../assets/sounds/alarm_siren.wav'),
};

export type SoundKey = keyof typeof SOURCES;

const players = new Map<SoundKey, AudioPlayer>();

export async function initSounds() {
  try {
    // Plays in silent mode and in the background (Drive-mode foreground service keeps JS alive).
    await setAudioModeAsync({ playsInSilentMode: true, shouldPlayInBackground: true, interruptionMode: 'duckOthers' });
  } catch (e) {
    console.warn('[sounds] audio mode', e);
  }
  for (const key of Object.keys(SOURCES) as SoundKey[]) {
    if (!players.has(key)) players.set(key, createAudioPlayer(SOURCES[key]));
  }
}

function start(player: AudioPlayer) {
  player.volume = 1;
  player
    .seekTo(0)
    .then(() => player.play())
    .catch(() => player.play());
}

export const sounds = {
  /** One-shot. Ignored while the same clip still plays, so ~1/s messages become a steady rhythm. */
  play(key: SoundKey) {
    const player = players.get(key);
    if (!player || player.playing) return;
    player.loop = false;
    start(player);
  },
  /** Loops until stop(). */
  loop(key: SoundKey) {
    const player = players.get(key);
    if (!player) return;
    player.loop = true;
    if (!player.playing) start(player);
  },
  stop(key: SoundKey) {
    const player = players.get(key);
    if (!player) return;
    player.loop = false;
    player.pause();
  },
};
